async function main(){
  let failed=0;const results=[];const selected=process.env.TEST_FILTER?tests.filter(t=>t.name.includes(process.env.TEST_FILTER)):tests;if(!selected.length)throw Error('TEST_FILTER matched no tests');
  for(const {name,body}of selected){const h=makeHarness();await withKey(h);try{await withTimeout(h.run(body));assert.equal(h.control.networkAttempts,0);console.log('PASS',name);results.push({name,pass:true,...(h.control.evidence.length?{evidence:h.control.evidence}:{})});}catch(e){failed++;console.log('FAIL',name,'\n ',e.stack);results.push({name,pass:false,error:e.message,...(h.control.evidence.length?{evidence:h.control.evidence}:{})});}}
  console.log('\n'+(selected.length-failed)+'/'+selected.length+' passed; offline Node VM + real WebCrypto + in-memory transaction mock.');
  if(process.env.RESULTS_JSON)fs.writeFileSync(process.env.RESULTS_JSON,JSON.stringify({scope:'Synthetic offline VM only; not production Firebase or full browser integration',generatedAt:new Date().toISOString(),nodeVersion:process.version,sourceSha256:require('node:crypto').createHash('sha256').update(html).digest('hex'),total:selected.length,passed:selected.length-failed,failed,results},null,2));
  process.exitCode=failed?1:0;
}
